.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--space-3) var(--space-6);
    font-weight: 500;
    border-radius: var(--radius);
    transition: var(--transition);
    text-align: center;
}

.btn-primary {
    background-color: var(--color-primary);
    color: white;
}
.btn-primary:hover {
    background-color: var(--color-primary-hover);
}

.btn-outline {
    border: 1px solid var(--color-primary);
    color: var(--color-primary);
}
.btn-outline:hover {
    background-color: var(--color-primary);
    color: white;
}

.icon-btn {
    padding: var(--space-2);
    border-radius: 50%;
}
.icon-btn:hover {
    background-color: var(--color-bg-alt);
}

.link-arrow {
    font-weight: 500;
    color: var(--color-text-muted);
}
.link-arrow:hover {
    color: var(--color-primary);
}

/* Header */
.site-header {
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    background-color: rgb(255 255 255 / 0.9);
    backdrop-filter: blur(8px);
    z-index: 50;
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 4rem;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    font-family: var(--font-serif);
    letter-spacing: -0.02em;
}

.nav-links {
    display: flex;
    gap: var(--space-6);
}

.nav-links a {
    font-weight: 500;
    color: var(--color-text-muted);
}
.nav-links a:hover {
    color: var(--color-text);
}

.header-actions {
    display: flex;
    gap: var(--space-2);
}

/* Hero */
.hero {
    padding: var(--space-16) 0;
    text-align: center;
    background-color: var(--color-bg-alt);
}

.hero-content {
    max-width: 800px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3rem;
    font-family: var(--font-serif);
    margin-bottom: var(--space-4);
    line-height: 1.2;
}

.hero p {
    font-size: 1.25rem;
    color: var(--color-text-muted);
    margin-bottom: var(--space-8);
    max-width: 600px;
    margin-inline: auto;
}

/* Product Cards */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--space-8) var(--space-6);
}

.product-card {
    position: relative;
    display: flex;
    flex-direction: column;
}

.product-image-wrapper {
    position: relative;
    aspect-ratio: 4/5;
    overflow: hidden;
    border-radius: var(--radius);
    background-color: var(--color-bg-alt);
    margin-bottom: var(--space-4);
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.product-label {
    position: absolute;
    top: var(--space-2);
    left: var(--space-2);
    background: var(--color-bg);
    color: var(--color-text);
    padding: 0.125rem var(--space-2);
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    border-radius: var(--radius);
    z-index: 1;
}

.sale-label {
    background: var(--color-accent);
    color: white;
}

.product-title {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: var(--space-1);
}

.product-link::after {
    content: '';
    position: absolute;
    inset: 0;
}

.product-price {
    color: var(--color-text-muted);
    font-weight: 500;
}

.original-price {
    text-decoration: line-through;
    color: var(--color-text-muted);
    opacity: 0.7;
    margin-left: var(--space-2);
    font-size: 0.875rem;
}

